import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

const BASE = process.env.REACT_APP_API_URL || "http://localhost:8080";

class WSService {
  constructor() {
    this.client = null;
    this.subscriptions = {};
    this.onConnectCb = null;
    this.onDisconnectCb = null;
  }

  connect(token, onConnect, onDisconnect) {
    this.onConnectCb = onConnect;
    this.onDisconnectCb = onDisconnect;

    this.client = new Client({
      webSocketFactory: () => new SockJS(`${BASE}/ws`),
      connectHeaders: { Authorization: `Bearer ${token}` },
      reconnectDelay: 3000,
      onConnect: () => {
        if (this.onConnectCb) this.onConnectCb();
      },
      onDisconnect: () => {
        if (this.onDisconnectCb) this.onDisconnectCb();
      },
      onStompError: (frame) => {
        console.error("STOMP error", frame);
      },
    });

    this.client.activate();
  }

  disconnect() {
    Object.values(this.subscriptions).forEach((sub) => {
      try { sub.unsubscribe(); } catch (_) {}
    });
    this.subscriptions = {};
    if (this.client) this.client.deactivate();
    this.client = null;
  }

  subscribeRoom(roomId, callback) {
    if (!this.client?.connected) return;
    if (this.subscriptions[roomId]) return;
    this.subscriptions[roomId] = this.client.subscribe(
      `/topic/room/${roomId}`,
      (frame) => {
        try { callback(JSON.parse(frame.body)); } catch (_) {}
      }
    );
  }

  unsubscribeRoom(roomId) {
    if (this.subscriptions[roomId]) {
      try { this.subscriptions[roomId].unsubscribe(); } catch (_) {}
      delete this.subscriptions[roomId];
    }
  }

  sendMessage(roomId, content, senderName, senderId) {
    if (!this.client?.connected) return false;
    this.client.publish({
      destination: "/app/chat.sendMessage",
      body: JSON.stringify({
        roomId,
        content,
        senderName,
        senderId,
        type: "CHAT",
      }),
    });
    return true;
  }

  get connected() {
    return !!this.client?.connected;
  }
}

export const wsService = new WSService();
